import hmac
import json

from payhook.errors import InvalidNotification


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    try:
        data = json.loads(raw_body.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise InvalidNotification()

    event_id = data.get('event_id')
    account_id = data.get('account_id')
    amount_minor = data.get('amount_minor')
    currency = data.get('currency')

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification()

    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification()

    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int) or amount_minor < 0:
        raise InvalidNotification()

    if not isinstance(currency, str) or len(currency) != 3 or not currency.isupper() or not currency.isascii():
        raise InvalidNotification()

    timestamp = headers.get('X-Pay-Timestamp')
    if not timestamp:
        raise InvalidNotification()

    try:
        timestamp_int = int(timestamp)
    except (ValueError, TypeError):
        raise InvalidNotification()

    if abs(timestamp_int - now) > 300:
        raise InvalidNotification()

    signature = headers.get('X-Pay-Signature')

    if signature is not None:
        if not signature.startswith('v1='):
            raise InvalidNotification()

        provided_digest = signature[3:]
        expected_digest = hmac.new(
            secret,
            timestamp.encode('ascii') + b'.' + raw_body,
            hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(provided_digest, expected_digest):
            raise InvalidNotification()
    else:
        receipt = headers.get('X-Pay-Receipt')
        if not receipt or not receipt.startswith('r0='):
            raise InvalidNotification()

        provided_digest = receipt[3:]
        expected_digest = hmac.new(
            secret,
            timestamp.encode('ascii') + b'.' + event_id.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(provided_digest, expected_digest):
            raise InvalidNotification()

    return {
        'event_id': event_id,
        'account_id': account_id,
        'amount_minor': amount_minor,
        'currency': currency
    }"}
